import{_ as r,l,o as t,c as s,v as e,p as n,x as i,d as p,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"焦距、物距与横向放大","description":"","frontmatter":{"title":"焦距、物距与横向放大","date":"2026-09-10T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/focal-magnification.md","filePath":"litho/focal-magnification.md","lastUpdated":1789023840000}'),d={name:"litho/focal-magnification.md"};function m(f,a,M,A,_,E){const o=l("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="焦距、物距与横向放大" tabindex="-1">焦距、物距与横向放大 <a class="header-anchor" href="#焦距、物距与横向放大" aria-label="Permalink to &quot;焦距、物距与横向放大&quot;">​</a></h1><div class="epigraph"><p>横向放大率等于像距与物距之比的负号；投影缩小把掩模图形按固定比例搬到晶圆，掩模 CD 与晶圆 CD 差一个 $|M|$。</p><footer>—— 据 Hecht, Optics 对 lateral magnification 与共轭关系的整理</footer></div><p><a href="/litho/thin-lens-equation">上一课</a>给出 \\(\\frac{1}{s}+\\frac{1}{s&#39;}=\\frac{1}{f}\\)。本课不重推该式。缺口是：像比物大还是小？\\(M\\) 与掩模尺寸、晶圆 CD、物像双方孔径如何一起约束？后课光瞳与视场都默认横向放大是已知数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>成像方程只含轴向距离，不直接说「掩模上 1 μm 在晶圆上是多少」。工程投影倍率常写 4:1 或 5:1，即 \\(|M|=1/4\\) 或 \\(1/5\\)。若不会 \\(M=-s&#39;/s\\)，无法把掩模图形与晶圆图形对应，也无法理解掩模缺陷缩小后为什么「看起来更小」（可印性仍是后课）。缺口是横向几何，不是再选一个焦距。</p><h3 id="倒像的负号不是缺陷" tabindex="-1">倒像的负号不是缺陷 <a class="header-anchor" href="#倒像的负号不是缺陷" aria-label="Permalink to &quot;倒像的负号不是缺陷&quot;">​</a></h3><p>\\(M\\lt 0\\) 表示倒像：物方朝上的箭头，像方朝下。光刻投影通常倒像，套刻与掩模版图在数据上已经折过取向。把 \\(|M|\\) 当成正数倍率没问题，但丢负号会在画光路时把上下搞反。本课保留负号，口头说「缩小四倍」时指绝对值。</p><p><span class="marginnote">\\(M=h&#39;/h=-s&#39;/s\\)。缩小：\\(|M|\\lt 1\\)，且由成像方程知 \\(|s&#39;|\\lt |s|\\)（会聚透镜、实像）。纵向放大约 \\(M^2\\)，焦深缩放后课才用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>近轴横向放大率如上。与成像方程联立：给定 \\(f\\) 与 \\(s\\)，先解 \\(s&#39;\\) 再得 \\(M\\)。固定 \\(f\\) 时，\\(s\\to f^+\\) 则 \\(|M|\\to\\infty\\)（显微镜工况）；\\(s\\gg f\\) 则 \\(|M|\\to 0\\)。投影光刻选中等缩小：掩模比晶圆大，便于制造与检验，又把物镜口径控制在可做的范围。</p><p>选 4:1 而不是 10:1，是掩模尺寸、物镜口径与视场的折中：缩得太狠，掩模上同一视场变得过大，或物方 NA 小到照明与对准都别扭。本课不优化这个数，只说明 \\(|M|\\) 一旦选定，掩模与晶圆上的所有横向尺寸都按它换算，包括下一课视场光阑在两边的开口。</p><p>物方 NA 与像方 NA 通过 \\(|M|\\) 关联（近轴、同一介质）：\\(\\mathrm{NA}_{\\mathrm{img}}\\approx |M|\\,\\mathrm{NA}_{\\mathrm{obj}}\\)。像方 NA 进入后课分辨率语言；物方 NA 决定掩模侧照明锥角。本课只把关系写下，不把分辨公式提前展开。</p>',12)),(t(),n(c,null,{default:i(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20GAUSS%5B%221%2Fs%20%2B%201%2Fs'%20%3D%201%2Ff%22%5D%20--%3E%20M%5B%22M%20%3D%20-s'%2Fs%22%5D%0A%20%20M%20--%3E%20MASK%5B%22%E6%8E%A9%E6%A8%A1%E5%B0%BA%E5%AF%B8%22%5D%0A%20%20M%20--%3E%20WAFER%5B%22%E6%99%B6%E5%9C%86%E5%9B%BE%E5%BD%A2%E5%B0%BA%E5%AF%B8%22%5D%0A%20%20MASK%20--%3E%20RATIO%5B%22%E7%BC%A9%E5%B0%8F%E6%8A%95%E5%BD%B1%E5%80%8D%E7%8E%87%22%5D%0A%20%20WAFER%20--%3E%20RATIO%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缩小使掩模上的误差与缺陷在晶圆上按 \\(|M|\\) 缩小——这是选 4:1 而不是 1:1 的经典理由之一。同时物镜要在像方张开更大的角，才能维持拉格朗日不变量（下一课 étendue 的近亲）。纵向放大 \\(M^2\\) 意味着物方离焦到像方会被「压扁」或「拉长」；\\(|M|=1/4\\) 时像方焦深对物方离焦不那么敏感，掩模轴向公差相对宽松。</p><p>畸变会让 \\(M\\) 随视场位置变，套刻把畸变当误差预算，而不是把本课的常数 \\(M\\) 作废。<a href="/litho/geometric-aberration-tour">几何像差一览</a> 再分类。各向异性倍率（某些 EUV 投影 \\(M_x\\neq M_y\\)）是机台特例，本课各向同性为零阶。</p><p>缩小还改掩模与晶圆上的缺陷「看起来」差一个 \\(|M|\\)：掩模上同样物理尺寸的缺陷，到晶圆按倍率缩小。可印性仍取决于缺陷的空间频率是否进得了光瞳，那是后课；本课只提供几何缩放。纵向放大 \\(M^2\\) 则让物方离焦映射到像方时被压缩，掩模轴向公差相对晶圆焦深更宽，这是选缩小投影的另一条几何理由。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课 paraxial、薄透镜、单色、无光阑。谁限制光束截面、视场有多大，是下一课 <a href="/litho/stop-pupil-fov">光阑、光瞳与视场</a>。也不讨论扫描狭缝如何把瞬时视场拼成全场。</p><p>纵向放大与折射率有关：物方、像方介质不同时，\\(M_{\\mathrm{long}}\\) 还要乘 \\(n\\) 的比。浸没只改像方时，焦深换算要小心。后课默认：投影倍率 \\(|M|\\) 已知；晶圆尺寸 = \\(|M|\\) 乘掩模尺寸；像方与物方孔径角差一个 \\(|M|\\)。谈到「4 倍缩小」，就是本课的 \\(|M|\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>横向放大 \\(M=-s&#39;/s\\)；投影缩小 \\(|M|\\lt 1\\)，通常倒像。</li><li>掩模 CD 与晶圆 CD 差 \\(|M|\\) 倍；物像双方 NA 也差 \\(|M|\\)。</li><li>纵向放大约 \\(M^2\\)，影响焦深与掩模轴向公差。</li><li>畸变使 \\(M\\) 随视场变，属像差，不改零阶定义。</li><li>出处：Hecht, <em>Optics</em>；Born &amp; Wolf, <em>Principles of Optics</em>。</li></ul>',9))])}const D=r(d,[["render",m]]);export{B as __pageData,D as default};
